def retry(operation, attempts, sleep):
    if attempts <= 0:
        raise ValueError('attempts must be positive')

    delay = 0.1
    for attempt in range(attempts):
        try:
            return operation()
        except TimeoutError:
            if attempt == attempts - 1:
                raise
            sleep(delay)
            delay = min(delay * 2, 1.0)
